function formatReadableDate(isoStr) {
  if (!isoStr || !/^\d{4}-\d{2}-\d{2}$/.test(isoStr)) return '';
  const [y, m, d] = isoStr.split('-').map(Number);
  if (m < 1 || m > 12) return '';
  return `${MONTH_SHORT[m - 1]} ${d}, ${y}`;
}

function isValidIsoDate(str) {
  if (!str || typeof str !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(str)) return false;
  const [y, m, d] = str.split('-').map(Number);
  if (m < 1 || m > 12 || d < 1 || d > 31) return false;
  const dt = new Date(y, m - 1, d);
  return dt.getFullYear() === y && dt.getMonth() === m - 1 && dt.getDate() === d;
}

function parseBasisPoints(percentStr) {
  const str = String(percentStr ?? '').trim();
  if (!str) return null;
  const match = str.match(/^(\d+)(?:\.(\d+))?$/);
  if (!match) return null;
  const intPart = parseInt(match[1], 10);
  const decPart = match[2] || '';
  if (decPart.length > 2) return null;
  const bp = intPart * 100 + (decPart.length === 1 ? parseInt(decPart, 10) * 10 : (decPart.length === 2 ? parseInt(decPart, 10) : 0));
  if (bp < 0 || bp > 10000) return null;
  return bp;
}

function calculateTotalBasisPoints(members) {
  if (!members || !members.length) return null;
  let totalBp = 0;
  for (const m of members) {
    const bp = parseBasisPoints(m.percent);
    if (bp === null) return null;
    totalBp += bp;
  }
  return totalBp;
}

