// Prototype Controller
window.pilot = {
  goto(screenId, statePreset) {
    let normScreen = (screenId || 'OB-01').toUpperCase().replace(/^SCREEN-/, '');
    if (normScreen === 'OB01') normScreen = 'OB-01';
    if (normScreen === 'OB02') normScreen = 'OB-02';
    if (normScreen === 'OB03') normScreen = 'OB-03';
    if (normScreen === 'SUMMARY' || normScreen === 'COMPLETE') normScreen = 'COMPLETE';

    let preset = statePreset || 'default';

    if (normScreen === 'SELECTED') {
      normScreen = 'OB-02';
      preset = 'selected';
    } else if (normScreen === 'COMPLETED') {
      normScreen = 'COMPLETE';
      preset = 'completed';
    } else if (normScreen === 'ERROR') {
      normScreen = 'OB-02';
      preset = 'validation-error';
    }

    state.currentScreen = normScreen;
    state.currentState = preset;
    state.openPicker = null;
    state.errors = {};

    // Apply state presets (separate demo presets from actual empty flow)
    if (normScreen === 'OB-02') {
      if (preset === 'populated' || preset === 'selected') {
        state.draft.name = 'Northstar Ventures LLC';
        state.draft.formationState = 'DE';
        state.draft.formationStateDisplay = 'Delaware';
        state.draft.formationDate = '2024-01-15';
        state.draft.bookkeepingStartDate = '2025-01-01';
        state.draft.taxClassification = 'unknown';
        state.draft.taxClassificationDisplay = 'Unknown / not yet determined';
      } else if (preset === 'validation-error' || preset === 'error') {
        state.draft.name = '';
        state.errors = { name: 'Legal business name is required.' };
      }
    } else if (normScreen === 'OB-03') {
      if (preset === 'template-applied' || preset === 'selected') {
        this.applyTemplate();
      } else if (preset === 'single') {
        this.setMemberMode('single');
      } else if (preset === 'blocked' || preset === 'error') {
        state.draft.members = [
          { id: makeId(), name: 'John Taylor', percent: '30.0' },
          { id: makeId(), name: 'Sarah Lee', percent: '20.0' }
        ];
        state.draft.ownershipConfirmed = false;
        state.errors = { members: 'Member ownership interests must total 100% (currently 50.00%).' };
      } else if (preset === 'confirmed') {
        if (!state.draft.members || !state.draft.members.length || !state.draft.members[0].name) {
          this.applyTemplate();
        }
        state.draft.ownershipConfirmed = true;
      }
    } else if (normScreen === 'COMPLETE') {
      if (preset === 'completed' || preset === 'summary') {
        if (!state.draft.name) {
          state.draft.name = 'Northstar Ventures LLC';
          state.draft.formationState = 'DE';
          state.draft.formationStateDisplay = 'Delaware';
          state.draft.formationDate = '2024-01-15';
          state.draft.bookkeepingStartDate = '2025-01-01';
          state.draft.taxClassification = 'unknown';
          state.draft.taxClassificationDisplay = 'Unknown / not yet determined';
        }
        this.saveCurrentWorkspace();
      }
    }

    this.render();
    this.closeModals();

    // Open modal if preset specifies
    if (preset === 'state-picker-open') this.openModal('state');
    if (preset === 'formation-picker-open') this.openModal('formation-date');
    if (preset === 'books-picker-open') this.openModal('books-date');
    if (preset === 'classification-picker-open') this.openModal('tax-classification');
  },

