submitOB03() {
  state.errors = {};
  const emptyMember = state.draft.members.some(m => !(m.name || '').trim());
  if (emptyMember) {
    state.errors.members = 'All members must have a legal name.';
    this.renderErrors();
    return;
  }
  const bp = calculateTotalBasisPoints(state.draft.members);
  if (bp === null) {
    state.errors.members = 'Member ownership interests must be valid percentages between 0 and 100 with at most 2 decimal places.';
    this.renderErrors();
    return;
  }
  if (bp !== 10000) {
    state.errors.members = `Total ownership is ${(bp / 100).toFixed(2)}%. It must equal exactly 100.0%.`;
    this.renderErrors();
    return;
  }
  if (!state.draft.ownershipConfirmed) {
    state.errors.members = 'Please confirm that the ownership interests shown are correct before continuing.';
    this.renderErrors();
    return;
  }
  this.saveCurrentWorkspace();
  this.goto('COMPLETE', 'summary');
},

saveCurrentWorkspace() {
  const copy = JSON.parse(JSON.stringify(state.draft));
  const existingIdx = state.workspaces.findIndex(w => w.id === copy.id);
  if (existingIdx >= 0) {
    state.workspaces[existingIdx] = copy;
  } else {
    state.workspaces.push(copy);
  }
  state.activeWorkspaceId = copy.id;
},

switchWorkspace(id) {
  this.saveCurrentWorkspace();
  const target = state.workspaces.find(w => w.id === id);
  if (target) {
    state.draft = JSON.parse(JSON.stringify(target));
    state.activeWorkspaceId = target.id;
    this.render();
  }
},

addAnotherLLC() {
  this.saveCurrentWorkspace();
  state.draft = createDefaultDraft();
  state.activeWorkspaceId = state.draft.id;
  this.goto('OB-02', 'default');
},

