renderMembers() {
  const container = document.getElementById('members-container');
  if (!container) return;
  container.innerHTML = '';

  state.draft.members.forEach((member, idx) => {
    const row = document.createElement('div');
    row.className = 'member-row';

    const nameTrimmed = (member.name || '').trim();
    const initials = nameTrimmed.split(/\s+/).filter(Boolean).map(n => n[0]).join('').toUpperCase().substring(0, 2) || 'M' + (idx + 1);

    row.innerHTML = `
      <div class="member-avatar"></div>
      <input class="member-name-input" type="text" placeholder="Member name" />
      <div class="member-percent-container">
        <input class="member-percent-input" type="text" />
        <span style="font-size:12.5px; color:var(--navy-muted);">%</span>
      </div>
      <button class="member-menu-btn" onclick="this.nextElementSibling.classList.toggle('active')">⋮</button>
      <div class="member-menu-dropdown">
        <button class="member-menu-item" onclick="window.pilot.removeMember(${idx})">Remove Member</button>
      </div>
    `;
    row.querySelector('.member-avatar').textContent = initials;
    const nameInp = row.querySelector('.member-name-input');
    nameInp.value = member.name || '';
    nameInp.oninput = (e) => window.pilot.updateMember(idx, 'name', e.target.value);
    const pctInp = row.querySelector('.member-percent-input');
    pctInp.value = member.percent != null ? String(member.percent) : '';
    pctInp.oninput = (e) => window.pilot.updateMember(idx, 'percent', e.target.value);
    container.appendChild(row);
  });

  const toggleMulti = document.getElementById('toggle-multi');
  const toggleSingle = document.getElementById('toggle-single');
